func:
// ==========================================================
// HA Monitor Display 屏幕通知 · payload 清洗
// ----------------------------------------------------------
// 兼容三种接线：①msg.message/msg.title 字符串
//              ②HA action 节点输出（msg.payload={message,title,...}）
//              ③msg.data 带原始数据
// 处理链：递归取值 → <br> 还原成换行 → 去链接/HTML/URL → 去井号（# 是屏幕着色语法）
//         → emoji 映射成彩色 MDI 图标 / 锚点位置补彩色占位 / 字形白名单过滤（挖掉方框）
//         → 按中文标签补行头图标（万能层） → 逐行 trim / 压空行 → 按 425px 硬折行
//         → UTF-8 安全截断 3400B → 加时间戳
// ==========================================================
function pick(v, depth) {
    if (v == null || depth > 4) return "";
    if (typeof v === "string") return v;
    if (typeof v === "number" || typeof v === "boolean") return String(v);
    if (Array.isArray(v)) {
        return v.map(x => pick(x, depth + 1)).filter(Boolean).join("\n");
    }
    if (typeof v === "object") {
        // notify 排第一：主流程（家居简报 / 尤萨洗衣 / 泰康养老）都是
        //   msg.notify 送 HA persistent_notification，也就是手机上看到的那份正文。
        //   屏幕要和手机一致，就得优先取它，而不是 payload.content（微信版，内容不同）。
        for (const k of ["notify", "message", "text", "content", "payload", "data"]) {
            if (k in v) {
                const s = pick(v[k], depth + 1);
                if (s) return s;
            }
        }
    }
    return "";
}
let text = "";
for (const cand of [msg.notify, msg.message, msg.payload, msg.data]) {
    text = pick(cand, 0);
    if (text) break;
}
let title = String(msg.title || (msg.payload && msg.payload.title) || (msg.data && msg.data.title) || "").trim();

// === 清洗：链接 / HTML / 裸 URL ===
//   ⚠️ 关键（11-01 第九轮）：上游通知全部用 <br> 分行 ——
//     家居简报 / 尤萨洗衣 / 泰康养老 都是 [...].join("<br>") 拼出来的，
//     再交给 HA 的 persistent_notification.create，HA App 会把 <br> 渲染成换行，
//     所以手机上看着是一行一条。但屏幕这边如果直接 .replace(/<[^>]+>/g," ")，
//     <br> 会被换成空格 → 原文的层级全丢，屏幕上就是一大段流水（用户反馈的
//     「没有按原格式换行」正是这个原因，跟设备端折行逻辑无关）。
//   所以先把块级标签还原成真换行，再清其余标签。
text = text
    .replace(/<br\s*\/?>/gi, "\n")                          // <br> <br/> <BR>
    .replace(/<\/(p|div|li|tr|h[1-6]|section|blockquote)>/gi, "\n")   // 块级结束
    .replace(/<(li|p|div|tr|h[1-6])\b[^>]*>/gi, "\n")         // 块级开头
    .replace(/&nbsp;/gi, " ")                              // HTML 实体
    .replace(/&lt;/gi, "<").replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
    .replace(/&amp;/gi, "&")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")        // markdown 图片 ![alt](url)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")       // markdown 链接 [text](url) → text
    .replace(/<img[^>]*>/gi, " ")                  // HTML 图片
    .replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, "$1")    // HTML 链接 → 文字
    .replace(/<[^>]+>/g, " ")                      // 其余 HTML 标签
    .replace(/https?:\/\/\S+/g, " ");              // 裸 URL

// === 井号必须先去：屏幕用 #RRGGBB 文本# 做内联着色，原文的 # 会破坏语法 ===
text = text.replace(/#/g, " ");

// === 图标方案（11-01 第十轮，「万能版」）：认字不认图 ===
//   图标 = MDI 码位（U+F0001 以上，4 字节 UTF-8），已经把字形并进正文用的
//   中文字体（fonts/NotoSansSC-SemiBold.ttf，见 .workbuddy/add_mdi_to_notify_font.py）。
//   内联着色语法：#RRGGBB 图标#（label 需 recolor: true）
//   三层，越往下越「万能」：
//     A. 语义 emoji：✅❌⚠️⭐♥🔔 与彩圆 —— 颜色本身有含义，映射成对应图标
//     B. 内容 emoji：☀🌙💧⚡💰📱… —— 常见那几个映射成图标
//     C. 兜底：映射不到的不删，在「行首 / 【】内」换成彩色 ●■★◆ 占位，
//        保住原来的对齐；句中装饰性的直接丢（见下方 scrub）
//   为什么不再逐个 emoji 建表：上游每个节点用的 emoji 都不一样（语音指令里
//   光是行头就有 🔊🧑‍🏫⏰📌🎯📢🚶，系统音量里是 ⏰✨✅💡🔶🔴🌙），
//   永远追不完；而中文标签（时间/温度/费用/场景/执行/音量）在自己所有
//   通知里是稳定的 —— 图标交给标签，才是「万能」。
const CP = (n) => String.fromCodePoint(n);
const mk = (cp, col) => "#" + col + " " + (cp === 0 ? "●" : CP(cp)) + "#";
const EMOJI_ICONS = [
    // ---- A. 语义（颜色即语义） ----
    [/[\u2705\u2611]/gu,                      0xF05E0, "59D98B"],  // check-circle 完成 / 开
    [/[\u274C\u2716\u2717\u2718]/gu,          0xF0159, "FF5252"],  // close-circle 失败 / 关
    [/\u26A0\uFE0F?/gu,                        0xF0026, "FFD54F"],  // alert 警告
    [/[\u2B50\u2605\u2728\u{1F31F}]/gu,        0xF04CE, "FFD54F"],  // star 星标 / 分节标记
    [/\u2764\uFE0F?/gu,                        0xF02D1, "FF5252"],  // heart
    [/\u{1F514}\u{1F515}/gu,                   0xF009A, "FFD54F"],  // bell
    // 彩色圆点在通知里基本是「项目符号」（🔴 客厅: 🔴 无人、🔶 休息模式…），
    //   不是状态。所以还原成同色圆点 ●，别用图标 —— 用对勾/叉会读成报警。
    [/\u{1F534}/gu,                            0, "FF5252"],
    [/[\u{1F7E0}\u{1F7E1}\u{1F7E2}\u{1F7E3}\u{1F7E8}]/gu, 0, "FFB74D"],
    [/\u{1F536}/gu,                            0, "FFB74D"],   // 🔶 大橙菱形（同为项目符号）
    [/\u{1F537}/gu,                            0, "5AA9FF"],   // 🔷 大蓝菱形
    [/\u{1F535}/gu,                            0, "5AA9FF"],
    [/\u26AB/gu,                               0, "757575"],
    [/\u26AA/gu,                               0, "FFFFFF"],
    // ---- B. 内容 ----
    [/[\u{1F4C5}\u{1F4C6}\u{1F5D3}]/gu,                    0xF00ED, "5AA9FF"],  // calendar 日期
    [/[\u23F0\u23F1\u23F2\u{1F551}-\u{1F567}]/gu,          0xF0150, "5AA9FF"],  // clock 时间
    [/[\u{1F4CD}\u{1F5FA}\u{1F9ED}]/gu,                    0xF034E, "59D98B"],  // map-marker 地点
    [/[\u{1F3E0}\u{1F3E1}]/gu,                             0xF02DC, "5AA9FF"],  // home 家
    [/[\u{1F3E2}\u{1F3EA}\u{1F3EC}\u{1F3ED}]/gu,           0xF04DC, "5AA9FF"],  // store 单位 / 店铺
    [/[\u{1F4B0}\u{1F4B4}\u{1F4B5}\u{1F4B6}\u{1F3E6}]/gu,  0xF0114, "59D98B"],  // cash 钱
    [/[\u{1F4B3}\u{1F194}\u{1F4C7}]/gu,                    0xF0FEF, "B39DFF"],  // credit-card 卡
    [/\u{1F9FA}/gu,                                        0xF072A, "5AA9FF"],  // washing-machine 衣物
    [/\u{1F321}\uFE0F?/gu,                                 0xF050F, "FFB74D"],  // thermometer 温度
    [/[\u{1F4A7}\u{1F4A6}]/gu,                             0xF058E, "5AA9FF"],  // water-percent 湿度
    [/[\u{1F4A8}\u{1F32C}]/gu,                             0xF059D, "59D98B"],  // weather-windy 风
    [/\u2600\uFE0F?|[\u{1F31E}\u{1F324}]/gu,               0xF0599, "FFD54F"],  // weather-sunny 晴
    [/[\u{1F311}-\u{1F31C}]/gu,                            0xF0594, "B39DFF"],  // weather-night 月
    [/\u2601\uFE0F?|[\u26C5\u{1F325}]/gu,                 0xF0590, "757575"],  // weather-cloudy 阴
    [/[\u2614\u26C8\u{1F327}]/gu,                          0xF0597, "5AA9FF"],  // weather-rainy 雨
    [/\u26A1\uFE0F?|[\u{1F329}\u{1F50C}]/gu,               0xF0241, "FFD54F"],  // flash 电
    [/\u{1F4A1}/gu,                                        0xF0335, "FFD54F"],  // lightbulb 灯
    [/\u{1F525}/gu,                                        0xF0238, "FF5252"],  // fire 火
    [/[\u{1F697}\u{1F698}\u{1F699}\u{1F69A}]/gu,           0xF010B, "5AA9FF"],  // car 车
    [/\u{1F4F6}/gu,                                        0xF0928, "59D98B"],  // wifi 信号
    [/\u260E\uFE0F?|[\u{1F4F1}\u{1F4DE}]/gu,               0xF011C, "5AA9FF"],  // cellphone 手机
    [/[\u{1F464}\u{1F468}\u{1F469}\u{1F9D1}]/gu,           0xF0004, "5AA9FF"],  // account 人
    [/[\u{1F465}\u{1F46A}]/gu,                             0xF000E, "B39DFF"],  // account-multiple 多人
    [/[\u{1F33F}\u{1F343}]/gu,                             0xF0D43, "59D98B"],  // air-filter 空气
    [/\u{1F32B}/gu,                                        0xF00B5, "757575"],  // blur 雾 / PM2.5
    [/\u{1F50B}/gu,                                        0xF0079, "59D98B"],  // battery 电量
    [/\u{1F916}/gu,                                        0xF070D, "4FD8FA"],  // robot-vacuum 扫地机
    [/[\u{1F50A}\u{1F3B5}\u{1F3B6}\u{1F508}]/gu,           0xF04C3, "B39DFF"],  // speaker 音量 / 音响
    [/\u2615\uFE0F?/gu,                                    0xF0176, "FFB74D"],  // coffee 咖啡 / 饮水
    [/[\u{1F6CF}\u{1F6CC}]/gu,                             0xF02E3, "B39DFF"],  // bed 卧室
    [/\u{1F6CB}\uFE0F?/gu,                                 0xF04B9, "FFB74D"],  // sofa 客厅
    [/\u{1F6BF}/gu,                                        0xF09A0, "5AA9FF"],  // shower 水房
    [/\u{1F4CA}/gu,                                        0xF029A, "B39DFF"],  // gauge 图表 / 气压
    [/[\u{1F4DD}\u{1F4CC}]/gu,                             0xF0369, "5AA9FF"],  // message 备注 / 标签
];
for (const [re, cp, col] of EMOJI_ICONS) {
    const rep = mk(cp, col);
    text = text.replace(re, rep);
    // title 不做图标替换（第十九轮）：标题栏是页面自己的固定样式（铃铛图标 +
    //   纯文字标题），上游带来的 emoji 一律不要变成图标标记塞进标题。
}

// ==== SCREEN_CHARSET_BEGIN ====
