//   —— 行首那一格既没有语义、折行时又最容易落单成「一行只有一颗星」，
//   索性不给。【】里仍然补（用户明确要求【】必须整齐有图标）。
const scrub = (line) => {
    let out = "", inBrk = false;
    for (const ch of line) {                 // for..of 按码位迭代，代理对不会被拆
        const cp = ch.codePointAt(0);
        if (isVarSel(cp)) continue;
        if (SAFE.has(ch)) {
            out += ch;
            if (ch === "【") inBrk = true;
            else if (ch === "】") inBrk = false;
            continue;
        }
        if (inBrk && isIconCp(cp)) out += GENERIC;   // 只在【】里补位
    }
    return out;
};
