    ["场景", 0xF02DC, "5AA9FF"], ["居家", 0xF02DC, "5AA9FF"],
    ["在家", 0xF02DC, "5AA9FF"], ["离家", 0xF02DC, "5AA9FF"],
    ["模式", 0xF04B9, "FFB74D"],
    // 人
    ["人体", 0xF0004, "5AA9FF"], ["有人", 0xF0004, "5AA9FF"],
    ["无人", 0xF0004, "757575"], ["客人", 0xF000E, "B39DFF"],
    // 设备 / 能耗
    ["音量", 0xF04C3, "B39DFF"], ["语音", 0xF04C3, "B39DFF"],
    ["音响", 0xF04C3, "B39DFF"], ["功率", 0xF0241, "FFD54F"],
    ["用电", 0xF0241, "FFD54F"], ["电量", 0xF0079, "59D98B"],
    ["灯", 0xF0335, "FFD54F"], ["空调", 0xF001B, "4FD8FA"],
    ["风扇", 0xF0210, "59D98B"], ["冰箱", 0xF0290, "4FD8FA"],
    ["洗衣机", 0xF072A, "5AA9FF"], ["扫地", 0xF070D, "4FD8FA"],
    ["车位", 0xF010B, "5AA9FF"],
    // 网络 / 终端
    ["网络", 0xF05A9, "59D98B"], ["信号", 0xF0928, "59D98B"],
    ["WiFi", 0xF05A9, "59D98B"], ["wifi", 0xF05A9, "59D98B"],
    ["手机", 0xF011C, "5AA9FF"], ["终端", 0xF011C, "5AA9FF"],
    // 事件
    ["指令", 0xF009A, "FFD54F"], ["通知", 0xF009A, "FFD54F"],
    ["提醒", 0xF009A, "FFD54F"], ["识别", 0xF0369, "5AA9FF"],
    ["响应", 0xF0369, "5AA9FF"], ["执行", 0xF05E0, "59D98B"],
    ["状态", 0xF05E0, "59D98B"], ["结果", 0xF05E0, "59D98B"],
    ["说明", 0xF0369, "FFD54F"], ["原因", 0xF0369, "B39DFF"],
];
// 去掉行首那一个已有的图标标记（emoji 映射来的），返回 { head, rest }
const splitMark = (s) => {
    // 18 轮：原来只剥「一个」标记，两个 emoji（⭐🌟）会被 scrub 各补一个，
    //   于是 【活动】 变成「双星号 + 语义图标」。这里把连续的标记全剥掉。
    const m = s.match(/^(?:\s*#[0-9a-fA-F]{6} *[^#]{1,2}#)+\s*/);
    return m ? ["#", s.slice(m[0].length)] : ["", s.replace(/^\s*/, "")];
};
// 去掉字符串里所有 recolor 标记，只留可见文字
const stripMarks = (s) => s.replace(/#[0-9a-fA-F]{6} *[^#]{1,2}#/g, "");
// 行尾若正好是一个完整标记，返回它（折行时要把标记连着后面的字一起挪下去）
const tailMark = (s) => {
    const m = /(#[0-9a-fA-F]{6} *[^#]{1,2}#)$/.exec(s);
    return m ? m[1] : "";
};
// 标记里那个字形的宽度（图标 12 / ASCII 7）
const markPx = (m) => {
    const g = /#[0-9a-fA-F]{6} *([^#]{1,2})#$/.exec(m);
    return g ? charPx(g[1]) : 12;
};
// === 补齐行头 / 【】里的图标（第十三轮：一定要有，判不出就用通用星号） ===
//   **每一个【】里面必定有一个图标**：
//     · 标签能判断（时间/温度/费用/场景…）→ 用语义图标
//     · 判断不出 → 用通用星号 ★（与 emoji 同为全角 12px，不破坏对齐）
//   第十六轮（用户：「【运行】还是没有图标」）——上一版只认「行首就是【」
//   （^\s*【），可真实载荷里常常不是这样：
//     · 「1.【运行】空调制冷」   ← 带序号
//     · 「家居简报｜【活动】…｜【运行】…」← 整段一行，只有第一个【】在“行首”之外
//     · 「### 【电器】…」        ← 上游加了 markdown 标题号
//   这些情况下整行一个图标都拿不到，于是同一屏里 活动 有、运行 没有。
//   现在改成**扫整行每一个【…】**，句中的、带序号的、一行好几个的，全部补满。
//   冒号行（「温度: 26℃」）不硬塞：判出来才换，判不出保持原样。
const findIcon = (label) => {
    for (const [kw, cp, col] of HEAD_ICONS) {
        if (label.indexOf(kw) >= 0) return mk(cp, col);
    }
    return "";
};
const tagBrk = (_m, inner) => {
    // ① 先把【】里**所有**标记和残留占位符号剥干净（可能不止一个）
    // ② 再补上**唯一一个**图标 —— 语义优先，判不出用通用星号
    //   18 轮用户报「【活动】为什么一个图标 2 个星星」，就是①没做全：
    //   两个 emoji 各补了一个星号，只剥掉第一个，剩下的又跟着图标显示出来。
    const rest = stripMarks(inner)
        .replace(/^[\s★☆✦✧●■◆◇○✓✔·・]+/, "")
        .trim();
    if (!rest) return _m;
    return "【" + (findIcon(rest.slice(0, 14)) || GENERIC) + " " + rest + "】";
};
const tagLine = (line) => {
    if (!line) return line;
    // 【…】长度上限从 24 放到 80：两个 emoji 的标签（「【⭐⭐ 活动】」）内层
    //   标记串有 27 个 UTF-16 单元，超过旧上限就整段匹配不上 → 一个都没补，
    //   屏上仍是「两个星星」。这是 19 轮没修掉的真正原因。
    let out = line.replace(/【([^【】]{0,80})】/g, tagBrk);
    if (out.indexOf("【") >= 0) {
        // 【】 前面如果还挂着行首图标（原载荷自带 emoji），连续几个一起剥掉，避免双图标
        return out.replace(/(?:#[0-9a-fA-F]{6}\s[^#]{1,2}#\s*)+(?=【)/g, "");
    }

    // 「xxx:」：有语义就换成语义图标；没有语义但原来有图标位 → 统一成星号
    const mC = out.match(/^\s*([^:：]{1,14})\s*[:：]/);
    if (!mC) return out;
    const label = splitMark(mC[1])[1].trim();
    const icon = findIcon(label);
    const [mark, rest] = splitMark(out);
    if (icon) return icon + " " + rest;
    if (mark.trim()) return GENERIC + " " + rest;
    return out;
};
text = text.split("\n").map(tagLine).join("\n");

// === 保险一：一个【】里最多一个图标 ===
//   tagBrk 是「剥干净再补一个」，但只要有一处漏改（超长标签、嵌套写法），
//   屏上就会出现「一个图标 + 两颗星」。这里对每一对【】做最终裁剪：
//   只留第一个标记，其余全删 —— 用户 19 轮实测「【活动】还有两个星星」就是这个。
const capBrkIcon = (line) => line.replace(/【[^【】]*】/g, (seg) => {
    let seen = false;
    return seg.replace(/#[0-9a-fA-F]{6} *[^#]{1,2}#/g, (m) => {
        if (!seen) { seen = true; return m; }
        return "";
    });
});

// === 保险二：行首的星星一律去掉 ===
//   用户：「新闻前面的星星换行了，如果解决不了，新闻前的星星不要了」。
//   通用占位与 ⭐ 映射用的是同一个字形（MDI star U+F04CE），程序分不出
//   「占位星」和「语义星」，而这两者的信息量本来就都是零，所以行首一律删；
//   语义图标（温度/费用/场景…）不受影响，照旧保留。
const STAR_CP = 0xF04CE;
const headIconCp = (line) => {
    const m = /^\s*#[0-9a-fA-F]{6} *([^#]{1,2})#/.exec(line);
    return m ? m[1].codePointAt(0) : -1;
};
const dropHeadStar = (line) => {
    let s = line;
    if (headIconCp(s) === STAR_CP) s = s.replace(/^\s*#[0-9a-fA-F]{6} *[^#]{1,2}#\s*/, "");
    return s.replace(/^[\s★☆✦✧]+/, "");     // 字面星号（上游直接用 ★ 当项目符号）
};
// 逐行处理：整行只有星号（删完变空）的直接丢，不留空行
{
    const outLines = [];
    for (const l of text.split("\n")) {
        const r = dropHeadStar(capBrkIcon(l));
        if (l.trim() !== "" && r.trim() === "") continue;
        outLines.push(r);
    }
    text = outLines.join("\n");
}

// === 按屏幕行宽硬折行（设备端 notify_store.h 有同样逻辑，两头双保险） ===
//   12px 字号口径：汉字/全角 12px、ASCII 7px、空格 3px
//   正文可用 450px，右留 25px → 每行 ≤425px
//   #RRGGBB 着色标记不计宽（LVGL recolor 语法，两个 # 之间的十六进制不占位置）
const LINE_PX = 425;
const NO_HEAD = "，。！？、；：）」』】》”’,.!?;:";
const charPx = (c) => {
    const cp = c.codePointAt(0);
    if (cp === 32) return 3;
    return cp < 0x80 ? 7 : 12;
};
// 词内字符：ASCII 字母数字 + . % / - : _ 以及 °
//   让 "PM2.5" "1006hPa" "3.33km/h" "27°C" 不被行宽劈开
const isWordCh = (c) => {
    const cp = c.codePointAt(0);
    if (cp >= 48 && cp <= 57) return true;            // 0-9
    if (cp >= 65 && cp <= 90) return true;            // A-Z
    if (cp >= 97 && cp <= 122) return true;           // a-z
    if (".%/-:_".indexOf(c) >= 0) return true;
    if (cp === 0xB0) return true;                     // °
    return false;
};

// === 条目断行：上游正文是一段到底的流水（"…0Klx  1.【天气】…  2.【室内】…"），
//     序号落在行中间时读起来还是一堵墙。这里把「空格 + 1~2 位数字 + . 或 、」
//     认成序号，在它前面断成新行。排除 "PM2.5"（前面非空格）与
//     "3.33km"（点后是数字）。与设备端 notify_store.h 的 split_items 完全同口径。
const splitItems = (s) => {
    let out = "", has = false, i = 0;
    const n = s.length;
    while (i < n) {
        if (s[i] === " " && s[i + 1] >= "0" && s[i + 1] <= "9") {
            let j = i + 1;
            while (j < n && s[j] >= "0" && s[j] <= "9" && j - (i + 1) < 2) j++;
            let after = -1, ok = false;
            if (s[j] === ".") {
                after = j + 1;
                ok = !(s[after] >= "0" && s[after] <= "9");
            } else if (s[j] === "、") {
                after = j + 1;
                ok = true;
            }
            if (ok && after > 0 && after < n && has) {
                while (out.endsWith(" ")) out = out.slice(0, -1);
                out += "\n";
                while (i < after && s[i] === " ") i++;
                out += s.slice(i, after);      // 序号连点一起抄
                i = after;
                has = true;
                continue;
            }
        }
        if (s[i] !== " " && s[i] !== "\n") has = true;
        out += s[i++];
    }
    return out;
};
text = splitItems(text);

const wrapLine = (line) => {
    let out = "", w = 0, i = 0;
    const N = line.length;
    // 换行助手：行尾若孤零零挂着一个图标标记，连它一起挪到下一行。
    //   否则屏幕上会出现「一行只有一个星星」—— 18 轮用户报的新闻简报就是
    //   这个：每条新闻前的星号落单，标题跑到下一行去了。
    const brk = () => {
        const tm = tailMark(out);
        const keep = tm !== "" && stripMarks(out).trim() !== "";
        if (keep) out = out.slice(0, -tm.length);
        out += "\n";
        w = 0;
        if (keep) { out += tm; w = markPx(tm); }
    };
    while (i < N) {
        // recolor 标记「#RRGGBB 字形#」整段当原子（16 轮）：
        //   只抄 #RRGGBB 会把折行断在和字形之间 —— 屏幕上是「上一行末尾一串
        //   #B39DFF、下一行图标还没颜色」，看着就是图标丢了。
        //   宽度只算字形本身（hex 与两侧 # 都不上屏）。
        if (line[i] === "#") {
            const mk1 = /^#[0-9a-fA-F]{6} *([^#]{1,2})#/.exec(line.slice(i, i + 14));
            if (mk1) {
                const mw = charPx(mk1[1]);
                if (w > 0 && w + mw > LINE_PX) { out += "\n"; w = 0; }
                out += mk1[0];
                w += mw;
                i += mk1[0].length;
                continue;
            }
        }
        if (line[i] === "#" && /^[0-9a-fA-F]{6}/.test(line.slice(i + 1, i + 7))) {
            out += line.slice(i, i + 7);
            i += 7;
            continue;
        }
        if (line[i] === "#") { out += "#"; i++; continue; }
        // 按「码位」取字符：图标是 U+F0001 以上的 4 字节字符，在 JS 里是两个
        //   UTF-16 单元（代理对）。按 line[i] 逐单元走会把一个图标算成两格
        //   （24px），行宽虚高、明明放得下也会折行。
        const c0 = String.fromCodePoint(line.codePointAt(i));
        const step = c0.length;
        // 词整段不拆：先量整段宽度，放不下就整体挪到下一行
        if (isWordCh(c0)) {
            let j = i, ww = 0;
            while (j < N) {
                const cj = String.fromCodePoint(line.codePointAt(j));
                if (!isWordCh(cj)) break;
                ww += charPx(cj);
                j += cj.length;
            }
            if (ww > LINE_PX) { ww = 0; j = i + step; }   // 超长词退化为逐字符
            if (ww > 0) {
                if (w > 0 && w + ww > LINE_PX) { brk(); }
                out += line.slice(i, j);
                w += ww;
                i = j;
                continue;
            }
        }
        const pw = charPx(c0);
        // 放不下就断；但禁则标点宁可挤在本行末尾，也不落到下一行行首
        if (w > 0 && w + pw > LINE_PX && NO_HEAD.indexOf(c0) < 0) {
            if (c0 === " ") { i += step; continue; }      // 折行处的空格吞掉
            brk();
        }
        out += c0;
        w += pw;
        i += step;
    }
    return out;
};

text = text.split("\n").map(wrapLine).join("\n");

// === 图标不许独占一行（18 轮） ===
//   上游若本来就是「★ / 换行 / 标题」两行，或者折行把标记留在了行首，
//   屏幕上就是「一行只有一个星号」。这里把这种行接回下一行。
const glueIconLines = (t) => {
    const out = [];
    let pend = "";
    for (const ln of t.split("\n")) {
        if (!ln.trim()) {                       // 真空行：段落分隔，原样保留
            if (pend) { out.push(pend); pend = ""; }
            out.push("");
            continue;
        }
        const bare = stripMarks(ln).replace(/[\s★☆✦✧●■◆◇○✓✔·・|｜]/g, "");
        if (bare === "") { pend += ln.replace(/^\s+/, ""); continue; }
        out.push(pend ? pend + " " + ln.replace(/^\s+/, "") : ln);
        pend = "";
    }
    if (pend) out.push(pend);
    return out.join("\n");
};
text = glueIconLines(text);

if (!title && !text) return null;                 // 空消息直接丢弃
if (!title) title = "通知";
if (title.length > 24) title = title.slice(0, 24);   // 设备端 TITLE_MAX=72B≈24 汉字

// === UTF-8 字节安全截断（设备端上限 3500B，MQTT 接收缓冲 4096B） ===
const MAXB = 3400;
const LIM  = MAXB - 3;                            // 给结尾省略号留 3 字节
if (Buffer.byteLength(text, "utf8") > MAXB) {
    let cut = LIM;
    while (cut > 0 && Buffer.byteLength(text.slice(0, cut), "utf8") > LIM) cut--;
    const nl = text.lastIndexOf("\n", cut);       // 尽量回退到行边界
    if (nl > MAXB * 0.5) cut = nl;
    text = text.slice(0, cut).trimEnd() + "…";
}

msg.payload = JSON.stringify({
    title: title,
    message: text,
    ts: Math.floor(Date.now() / 1000)             // Unix 秒，屏幕显示 2026-11-01 18:07
});
return msg;
